//! Runtime COMBINE execution boundary.
use crate::combine::{bond_strength,eligible_candidates,required_investment,ExperimentalInteraction,FormationEvaluation};use crate::contact::ConnectionCompatibilityCache;use crate::resources::{BaseResource,ConnectionSites};use crate::state::{Environment,Organism};use crate::structure::{BondEndpoint,ConnectionEndpoint,Placement,StructuralUnit};
const EPSILON:f64=1e-12;const COMBINE_CONTACT_TOLERANCE:f64=1.0;
#[derive(Clone,Copy,Debug,PartialEq)]pub(crate)struct CombineAttempt{pub unit_a:usize,pub unit_b:usize,pub endpoint_a:ConnectionEndpoint,pub endpoint_b:ConnectionEndpoint,pub work_cost:f64,pub energy_invested:f64,pub interaction_direction:f64,pub interaction_magnitude:f64,pub interaction_energy:f64,pub formation_threshold:f64,pub net_energy_change:f64,pub bond_strength:f64,pub bond_energy:f64}
fn water_field_amount(e:&Environment,o:&Organism)->f64{o.occupied_cells.first().and_then(|p|e.field.index_for_position(p.x,p.y)).map(|i|e.field.cells[i].materials.iter().map(|m|if let Some(s)=m.structure(){s.constituents.iter().filter(|c|c.resource=="Water").count()as f64}else{m.composition().iter().filter(|c|c.resource=="Water").map(|c|c.amount).sum()}).sum()).unwrap_or(0.0)}
fn energy_requirement(i:f64,w:f64,x:f64)->Option<f64>{if !i.is_finite()||i<0.0||!w.is_finite()||w<0.0||!x.is_finite(){None}else{Some((i+w-x).max(0.0))}}
fn settle_energy(e:&mut f64,i:f64,w:f64,x:f64)->Option<f64>{let r=energy_requirement(i,w,x)?;if *e+EPSILON<r{return None}let net=x-i-w;let next=*e+net;if !net.is_finite()||!next.is_finite()||next< -EPSILON{return None}*e=next.max(0.0);Some(net)}
fn evaluate_candidate(s:&crate::structure::OrganismStructure,a:usize,b:usize,c:crate::contact::ConnectionPairCandidate,cat:&[BaseResource],water:f64)->Option<(FormationEvaluation,ExperimentalInteraction,f64,f64,f64)>{if c.distance>COMBINE_CONTACT_TOLERANCE{return None}let pa=s.units.get(a)?.properties(cat)?;let pb=s.units.get(b)?.properties(cat)?;let e=crate::combine::evaluate_formation(c,pa.cohesion,pb.cohesion);let(i,w,inv)=required_investment(pa,pb,e,water).ok()?;Some((e,i,w,inv,energy_requirement(inv,w,i.signed_value)?))}
fn form_bond(s:&mut crate::structure::OrganismStructure,a:usize,b:usize,ea:ConnectionEndpoint,eb:ConnectionEndpoint,investment:f64,water:f64,cat:&[BaseResource],cache:&mut ConnectionCompatibilityCache,energy:&mut f64)->Option<CombineAttempt>{let c=crate::contact::connection_pair_candidates_cached(s,a,b,cat,cache).into_iter().find(|c|c.endpoint_a==ea&&c.endpoint_b==eb&&c.distance<=COMBINE_CONTACT_TOLERANCE)?;let(pa,pb)=(s.units[a].properties(cat)?,s.units[b].properties(cat)?);let ev=crate::combine::evaluate_formation(c,pa.cohesion,pb.cohesion);if !crate::combine::formation_succeeds(ev,investment){return None}let(i,w,threshold)=required_investment(pa,pb,ev,water).ok()?;if(threshold-investment).abs()>EPSILON{return None}let strength=bond_strength(pa,pb);let mut trial=s.clone();crate::contact::try_add_bond(&mut trial,crate::structure::Bond{endpoint_a:BondEndpoint{unit_index:a,location:ea},endpoint_b:BondEndpoint{unit_index:b,location:eb},strength,bond_energy:investment},cat).ok()?;let mut next=*energy;let net=settle_energy(&mut next,investment,w,i.signed_value)?;*s=trial;*energy=next;Some(CombineAttempt{unit_a:a,unit_b:b,endpoint_a:ea,endpoint_b:eb,work_cost:w,energy_invested:investment,interaction_direction:i.direction,interaction_magnitude:i.magnitude,interaction_energy:i.signed_value,formation_threshold:threshold,net_energy_change:net,bond_strength:strength,bond_energy:investment})}
fn placement_for_corner(existing:&StructuralUnit,existing_point:crate::resources::ConnectionPoint,new_point:crate::resources::ConnectionPoint)->Placement{let world=crate::contact::world_connection_point(existing_point,existing);let angle=world.normal_y.atan2(world.normal_x);let rotation=angle+std::f64::consts::PI-new_point.direction_radians;let(s,c)=rotation.sin_cos();let x=new_point.x*c-new_point.y*s;let y=new_point.x*s+new_point.y*c;Placement{x:world.x-x,y:world.y-y,rotation_radians:rotation}}
pub(crate)fn instantiate_one_unit(o:&mut Organism,cat:&[BaseResource])->Option<usize>{let m=o.stored_material.peek_one_unstructured()?;let[c]=m.composition()else{return None};if(c.amount-1.0).abs()>EPSILON||cat.iter().all(|r|r.name!=c.resource){return None}let name=c.resource.clone();let m=o.stored_material.take_one_unstructured_named(&name)?;let(x,y)=o.occupied_cells.first().map(|p|(p.x,p.y)).unwrap_or((0.0,0.0));Some(o.structure.add_unit(StructuralUnit::from_material(m,Placement{x,y,rotation_radians:0.0})?))}
pub(crate)fn try_combine_stored_unit(o:&mut Organism,e:&Environment,cache:&mut ConnectionCompatibilityCache)->Option<CombineAttempt>{let raw=o.stored_material.peek_one_unstructured()?;let[c]=raw.composition()else{return None};if(c.amount-1.0).abs()>EPSILON{return None}let name=c.resource.clone();let resource=e.catalog.iter().find(|r|r.name==name)?;let ConnectionSites::Corners(new_sites)=resource.shape.connection_sites()else{return None};let water=water_field_amount(e,o);let mut best=None;for ua in 0..o.structure.units.len(){let Some(ConnectionSites::Corners(existing))=o.structure.units[ua].connection_sites(&e.catalog)else{continue};for(ep_a,point_a)in existing.iter().enumerate(){for(ep_b,point_b)in new_sites.iter().enumerate(){let placement=placement_for_corner(&o.structure.units[ua],*point_a,*point_b);let mut trial=o.structure.clone();let ub=trial.add_unit(StructuralUnit::new(name.clone(),placement));let Some(candidate)=crate::contact::connection_pair_candidates_cached(&trial,ua,ub,&e.catalog,cache).into_iter().find(|c|c.endpoint_a==ConnectionEndpoint::Corner{point_index:ep_a}&&c.endpoint_b==ConnectionEndpoint::Corner{point_index:ep_b})else{continue};let Some((ev,_,_,investment,required))=evaluate_candidate(&trial,ua,ub,candidate,&e.catalog,water)else{continue};if o.usable_energy+EPSILON<required{continue}if best.as_ref().map(|x:(usize,usize,FormationEvaluation,f64)|candidate.distance<x.3).unwrap_or(true){best=Some((ua,ub,ev,investment));}}}}let(ua,ub,ev,investment)=best?;let mut energy=o.usable_energy;let attempt=form_bond(&mut o.structure,ua,ub,ev.candidate.endpoint_a,ev.candidate.endpoint_b,investment,water,&e.catalog,cache,&mut energy)?;o.stored_material.take_one_unstructured_named(&name)?;o.usable_energy=energy;o.add_transaction_stress(attempt.work_cost);Some(attempt)}
pub(crate)fn try_combine(o:&mut Organism,e:&Environment,cache:&mut ConnectionCompatibilityCache)->Option<CombineAttempt>{if !o.structure.units.is_empty(){if let Some(a)=try_combine_stored_unit(o,e,cache){return Some(a)}}if o.structure.units.len()<2{return None}let water=water_field_amount(e,o);let mut best=None;for a in 0..o.structure.units.len(){for b in a+1..o.structure.units.len(){for c in eligible_candidates(&o.structure,a,b,&e.catalog,cache){let Some((ev,_,_,investment,required))=evaluate_candidate(&o.structure,a,b,c,&e.catalog,water)else{continue};if o.usable_energy+EPSILON<required{continue}if best.as_ref().map(|x:(usize,usize,FormationEvaluation,f64,f64)|c.distance<x.4).unwrap_or(true){best=Some((a,b,ev,investment,required));}}}}let(a,b,ev,investment,_)=best?;let mut energy=o.usable_energy;let attempt=form_bond(&mut o.structure,a,b,ev.candidate.endpoint_a,ev.candidate.endpoint_b,investment,water,&e.catalog,cache,&mut energy)?;o.usable_energy=energy;o.add_transaction_stress(attempt.work_cost);Some(attempt)}
